import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/skills/commands.md","filePath":"modules/skills/commands.md","lastUpdated":0}`),a={name:`modules/skills/commands.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to “命令与权限”">​</a></h1><p>EmakiSkills 的命令和权限节点如下, 包括玩家用的功能命令, 管理员用的管理命令, 以及每条命令要配什么权限</p><p>EmakiSkills 的主命令是 <code>/emakiskills</code>, 别名 <code>/eskills</code>. 玩家用它打开技能界面, 切换施法模式和升级技能; 管理员用它管理等级, 授予或收回技能, 清空槽位, 检查档案, 重新扫描技能来源和重载配置</p><h2 id="命令注册" tabindex="-1">命令注册 <a class="header-anchor" href="#命令注册" aria-label="Permalink to “命令注册”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>主命令</td><td><code>/emakiskills</code></td></tr><tr><td>别名</td><td><code>/eskills</code></td></tr><tr><td>命令注册权限</td><td><code>emakiskills.use</code></td></tr><tr><td>命令提示</td><td><code>/eskills</code> 或 <code>/eskills help</code></td></tr></tbody></table><p>记住一点: 整条命令都挂在 <code>emakiskills.use</code> 权限下. 缺了这个权限, 连 <code>help</code> 在内的所有子命令都执行不了, 子命令里那个 <code>emakiskills.admin</code> 的备用权限判断也轮不到. 这个权限默认是 <code>true</code>, 所以实际能拦住人的, 主要是服主在权限插件里显式取消 (取反) 的情况</p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to “命令列表”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/eskills help</code></td><td>命令注册权限</td><td>输出命令帮助列表. 不带参数直接执行 <code>/eskills</code> 也会显示同样的内容. help 分支自己不再额外检查权限</td></tr><tr><td><code>/eskills gui</code></td><td><code>emakiskills.use</code> 或 <code>emakiskills.admin</code></td><td>打开技能 GUI. 控制台这类非玩家来执行会提示仅限玩家</td></tr><tr><td><code>/eskills castmode &lt;on|off|toggle&gt;</code></td><td><code>emakiskills.use</code> 或 <code>emakiskills.admin</code></td><td>开启, 关闭或切换施法模式</td></tr><tr><td><code>/eskills upgrade &lt;skill&gt;</code></td><td><code>emakiskills.use</code> 或 <code>emakiskills.admin</code></td><td>尝试升级指定技能, 反馈文案来自 <code>upgrade.*</code></td></tr><tr><td><code>/eskills level get &lt;player&gt; &lt;skill&gt;</code></td><td><code>emakiskills.admin</code></td><td>查看某个玩家某个技能的等级</td></tr><tr><td><code>/eskills level set &lt;player&gt; &lt;skill&gt; &lt;value&gt;</code></td><td><code>emakiskills.admin</code></td><td>设置某个玩家某个技能的等级</td></tr><tr><td><code>/eskills level add &lt;player&gt; &lt;skill&gt; &lt;value&gt;</code></td><td><code>emakiskills.admin</code></td><td>增加某个玩家某个技能的等级</td></tr><tr><td><code>/eskills grant &lt;player&gt; &lt;skill&gt;</code></td><td><code>emakiskills.admin</code></td><td>把技能写进玩家的手动已学集合, 并存到 <code>data/&lt;uuid&gt;.yml</code> 的 <code>manual_skill_ids</code>. 目标技能 id 没有定义 (YAML 或外部注册) 时回复 <code>skill.not_found</code></td></tr><tr><td><code>/eskills revoke &lt;player&gt; &lt;skill&gt;</code></td><td><code>emakiskills.admin</code></td><td>从玩家的手动已学集合移除技能并保存. 目标技能 id 没有定义时同样回复 <code>skill.not_found</code></td></tr><tr><td><code>/eskills list [player]</code></td><td><code>emakiskills.use</code> 或 <code>emakiskills.admin</code></td><td>只读列出玩家已学的技能和槽位绑定, 省略玩家时看自己</td></tr><tr><td><code>/eskills reset &lt;player&gt;</code></td><td><code>emakiskills.admin</code></td><td>清空玩家的手动已学技能, 槽位绑定不受影响</td></tr><tr><td><code>/eskills clearslot &lt;player&gt; &lt;slot&gt;</code></td><td><code>emakiskills.admin</code></td><td>清空玩家指定技能槽的绑定</td></tr><tr><td><code>/eskills inspect [player]</code></td><td><code>emakiskills.use</code> 或 <code>emakiskills.admin</code></td><td>查看玩家的技能档案和已绑定的触发器槽位</td></tr><tr><td><code>/eskills resync [player]</code></td><td><code>emakiskills.admin</code></td><td>校验并重新同步玩家的技能槽绑定, 省略玩家时可以作用在自己身上</td></tr><tr><td><code>/eskills debug [status|on|off|player|module] [...]</code></td><td><code>emakiskills.debug</code> 或 <code>emakiskills.admin</code></td><td>输出或切换调试状态. 技能模块有 <code>cast</code>, <code>unlock</code>, <code>upgrade</code>, <code>slot</code> 四个</td></tr><tr><td><code>/eskills reload</code></td><td><code>emakiskills.reload</code> 或 <code>emakiskills.admin</code></td><td>异步重载技能, 资源, GUI, 语言和主配置, 并输出耗时</td></tr></tbody></table><p>你输错子命令时, 会收到 <code>general.unknown_command</code> 的回复. <code>level</code> 和 <code>clearslot</code> 还会检查参数个数以及整数 <code>value</code>/<code>slot</code> 是否合法, 不合法就回复 <code>general.invalid_args</code></p><h3 id="参数补全" tabindex="-1">参数补全 <a class="header-anchor" href="#参数补全" aria-label="Permalink to “参数补全”">​</a></h3><table tabindex="0"><thead><tr><th>位置</th><th>补全内容</th></tr></thead><tbody><tr><td>第 1 参数</td><td>补出十四个子命令本身</td></tr><tr><td><code>castmode</code> 第 2 参数</td><td>补出 <code>on</code>, <code>off</code>, <code>toggle</code></td></tr><tr><td><code>upgrade</code> 第 2 参数</td><td>补出玩家已解锁, 已开启升级且还没满级的技能 id; 控制台执行时补出全部技能 id</td></tr><tr><td><code>level</code> 第 2 参数</td><td>补出 <code>get</code>, <code>set</code>, <code>add</code></td></tr><tr><td><code>clearslot</code> / <code>grant</code> / <code>revoke</code> / <code>list</code> / <code>reset</code> / <code>inspect</code> / <code>resync</code> 第 2 参数, <code>level</code> 第 3 参数</td><td>补出在线玩家名</td></tr><tr><td><code>grant</code> / <code>revoke</code> 第 3 参数</td><td>补出全部技能 id</td></tr><tr><td><code>clearslot</code> 第 3 参数</td><td>补出槽位 <code>0</code>~<code>8</code></td></tr><tr><td><code>level</code> 第 4 参数</td><td>补出全部技能 id</td></tr><tr><td><code>level set/add</code> 第 5 参数</td><td>补出 <code>1</code>, <code>2</code>, <code>5</code>, <code>10</code></td></tr></tbody></table><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to “权限节点”">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>emakiskills.use</code></td><td>true</td><td>允许使用基础技能功能, 打开 GUI, 切换施法模式和释放技能; 同时也是命令的注册权限</td></tr><tr><td><code>emakiskills.reload</code></td><td>op</td><td>允许重载配置</td></tr><tr><td><code>emakiskills.admin</code></td><td>op</td><td>允许管理技能等级, 清空槽位, 重新同步, 也作为基础功能的管理员备用权限</td></tr><tr><td><code>emakiskills.debug</code></td><td>op</td><td>允许输出调试信息</td></tr></tbody></table><h2 id="先用哪个命令" tabindex="-1">先用哪个命令 <a class="header-anchor" href="#先用哪个命令" aria-label="Permalink to “先用哪个命令”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>先执行</th><th>目的</th></tr></thead><tbody><tr><td>玩家要查看或绑定技能</td><td><code>/eskills gui</code></td><td>打开技能界面</td></tr><tr><td>主动技能无法释放</td><td><code>/eskills inspect [player]</code></td><td>看看玩家档案有没有加载, 以及已绑定的触发器槽位现在是什么状态</td></tr><tr><td>玩家换装备后技能没刷新</td><td><code>/eskills resync &lt;player&gt;</code></td><td>重新扫描一遍技能来源</td></tr><tr><td>技能等级异常</td><td><code>/eskills level get &lt;player&gt; &lt;skill&gt;</code></td><td>确认玩家档案里真实的等级是多少</td></tr><tr><td>槽位绑定到已删除技能</td><td><code>/eskills clearslot &lt;player&gt; &lt;slot&gt;</code></td><td>清理指定的技能槽</td></tr><tr><td>要直接给玩家授予或收回技能</td><td><code>/eskills grant</code> / <code>/eskills revoke</code></td><td>写入或移除玩家的手动已学技能</td></tr><tr><td>改了技能, 资源或 GUI</td><td><code>/eskills reload</code></td><td>重载运行配置</td></tr></tbody></table><h2 id="常见操作" tabindex="-1">常见操作 <a class="header-anchor" href="#常见操作" aria-label="Permalink to “常见操作”">​</a></h2><h3 id="打开技能界面" tabindex="-1">打开技能界面 <a class="header-anchor" href="#打开技能界面" aria-label="Permalink to “打开技能界面”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills gui</span></span></code></pre></div><p>打开技能界面后, 你能看到已解锁的技能, 技能等级, 槽位绑定, 升级入口和触发器选择入口</p><h3 id="切换施法模式" tabindex="-1">切换施法模式 <a class="header-anchor" href="#切换施法模式" aria-label="Permalink to “切换施法模式”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills castmode toggle</span></span>
<span class="line"><span>/eskills castmode on</span></span>
<span class="line"><span>/eskills castmode off</span></span></code></pre></div><p>施法模式决定主动技能能不能触发. 默认配置里你按 F 键就能进入或退出施法模式; 玩家重登后要不要恢复上次的状态, 由 <code>cast_mode.restore_last_state_on_join</code> 控制</p><h3 id="管理技能等级" tabindex="-1">管理技能等级 <a class="header-anchor" href="#管理技能等级" aria-label="Permalink to “管理技能等级”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills level get Steve fireball</span></span>
<span class="line"><span>/eskills level set Steve fireball 3</span></span>
<span class="line"><span>/eskills level add Steve fireball 1</span></span></code></pre></div><p>等级会直接影响技能参数, 资源消耗, 脚本变量和升级判断. 等级会被限制在 <code>[1, max_level]</code> 之间; 没开升级的技能最大等级就是 <code>1</code>. 改完后用 <code>inspect</code> 看一眼, 确认玩家档案里的等级已经更新</p><h3 id="授予与移除技能" tabindex="-1">授予与移除技能 <a class="header-anchor" href="#授予与移除技能" aria-label="Permalink to “授予与移除技能”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills grant Steve fireball</span></span>
<span class="line"><span>/eskills revoke Steve fireball</span></span></code></pre></div><p><code>grant</code> 把技能写进玩家的手动已学集合, <code>revoke</code> 再把它从集合里拿掉. 两条命令都要求目标技能 id 已经定义 (<code>skills/</code> 里的 YAML 技能或外部注册的技能), 否则回复 <code>skill.not_found</code>. 结果会保存到 <code>data/&lt;uuid&gt;.yml</code> 的 <code>manual_skill_ids</code></p><h3 id="查看玩家已学技能" tabindex="-1">查看玩家已学技能 <a class="header-anchor" href="#查看玩家已学技能" aria-label="Permalink to “查看玩家已学技能”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills list</span></span>
<span class="line"><span>/eskills list Steve</span></span></code></pre></div><p>这条命令只列出玩家已学 (手动解锁) 的技能和槽位绑定, 只读不改; 省略玩家时看自己</p><h3 id="重置手动已学技能" tabindex="-1">重置手动已学技能 <a class="header-anchor" href="#重置手动已学技能" aria-label="Permalink to “重置手动已学技能”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills reset Steve</span></span></code></pre></div><p>这条命令只清空玩家的手动已学技能, 只影响 <code>manual_skill_ids</code>, 槽位绑定不受影响; 要清理槽位请改用 <code>clearslot</code></p><h3 id="清空技能槽" tabindex="-1">清空技能槽 <a class="header-anchor" href="#清空技能槽" aria-label="Permalink to “清空技能槽”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills clearslot Steve 1</span></span></code></pre></div><p>碰到下面这些情况, 你可以用这条命令清理指定的槽位: 玩家的槽位绑到了已删除的技能, 触发器冲突, 或 GUI 里怎么都解绑不了. 槽位不合法时状态服务会拒绝并返回失败</p><h3 id="重新扫描技能来源" tabindex="-1">重新扫描技能来源 <a class="header-anchor" href="#重新扫描技能来源" aria-label="Permalink to “重新扫描技能来源”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills resync Steve</span></span></code></pre></div><p>下面几种情况适合用它:</p><ul><li>玩家换了装备, 但技能来源没有马上刷新</li><li>EmakiItem 套装或物品效果发生了变化</li><li>外部模块发放或移除了技能来源</li><li>重载配置后要刷新在线玩家状态</li></ul><h3 id="输出调试信息" tabindex="-1">输出调试信息 <a class="header-anchor" href="#输出调试信息" aria-label="Permalink to “输出调试信息”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills debug</span></span>
<span class="line"><span>/eskills debug status</span></span>
<span class="line"><span>/eskills debug on</span></span>
<span class="line"><span>/eskills debug off</span></span>
<span class="line"><span>/eskills debug player Steve</span></span>
<span class="line"><span>/eskills debug module cast</span></span></code></pre></div><table tabindex="0"><thead><tr><th>子命令</th><th>说明</th></tr></thead><tbody><tr><td><code>status</code></td><td>输出当前调试状态和正在跟踪的玩家; <code>debug</code> 不带参数时也会输出状态, 认不出的子命令也回落到状态输出</td></tr><tr><td><code>on</code> / <code>off</code></td><td>打开或关闭全部调试输出</td></tr><tr><td><code>player &lt;玩家&gt;</code></td><td>跟踪指定玩家的调试输出</td></tr><tr><td><code>module &lt;模块&gt;</code></td><td>切换单个调试模块. 技能模块有 <code>cast</code>, <code>unlock</code>, <code>upgrade</code>, <code>slot</code>; 共享模块有 <code>action</code>, <code>item_operation</code>, <code>variables</code>, <code>placeholder</code>, <code>gui</code>, <code>chat_input</code></td></tr></tbody></table><p>注意: 命令帮助里写的是 <code>debug &lt;status|player|module|all&gt; [...]</code>, 实际能用的子命令以上面这节为准</p><h2 id="排查建议" tabindex="-1">排查建议 <a class="header-anchor" href="#排查建议" aria-label="Permalink to “排查建议”">​</a></h2><ul><li>技能不显示: 检查技能定义是否加载, 你有没有技能来源, 技能等级是否大于 0</li><li>技能无法释放: 检查施法模式, 触发器绑定, 冷却, 全局延迟, 资源消耗和条件</li><li>被动技能不触发: 检查 <code>trigger_type: passive</code>, <code>passive_triggers</code> 和全局被动触发器是否启用</li><li>GUI 绑定失败: 检查触发器是否禁用, 是否与已有触发器冲突, 槽位编号是否有效</li><li>MythicMobs 技能无效果: 检查 MythicMobs 是否安装, 技能 ID 是否正确, 脚本模式是否为 <code>mythic</code> 或 <code>hybrid</code></li><li>玩家看不到失败原因: 文案取自 <code>lang/&lt;language&gt;.yml</code>; 确认该语言文件里有对应键, 不要直接去改源码里的 reasonKey</li></ul>`,47)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};